      "description": "젠지 세대(20대)를 위한 오감독서 4기 <마음 클럽> 참여자 모집\n○ 운영기간 : 2026. 10. 15.(목) 19:00~21:00\n10. 17.(토) 14:00~16:00 /  10. 17.(토) 16:00~18:00\n10. 22.(목) 19:00~21:00 [4회]\n○ 접수기간 :\n2026. 9. 21.(월) 10:00 ~ 2026. 10. 14.(수) 17:00\n○ 접수방법 : 성남시 평생학습포털 통합플랫폼 '배움숲' 온라인 선착순 접수\n(\n바로가기\n)\n○ 접수대상:\n20대 젠지세대(1995년~2006년생)\n○ 접수인원: 16명(3일, 4회차 강의를 모두 참여하실 분을 모집합니다. 한 책을 온전히 읽기 위한 프로그램 입니다. 1회성 참여는 다른 분들을 위해서 자제해 주세요.)\n○ 운영장소 : 제1문",
